import { InvalidValueException, NullValueException, UndefinedValueException } from './exceptions';

/**
 * Parse a string to a bool
 *
 * @export
 * @param {(string | null | undefined)} value
 * @param {string} [propertyName]
 * @returns {boolean}
 * @throws {NullValueException}
 * @throws {UndefinedValueException}
 * @throws {InvalidValueException}
 */
export function parseBool(value: string | null | undefined, propertyName?: string): boolean {
    if (value === null) {
        throw new NullValueException('bool', propertyName);
    }

    if (value === void 0) {
        throw new UndefinedValueException('bool', propertyName);
    }

    switch (value.toLowerCase()) {
        case 'true':
            return true;
        case 'false':
            return false;
        default:
            throw new InvalidValueException('bool', value, propertyName);
    }
}
